function isPerfectSquare(x) {
    const s = Math.floor(Math.sqrt(x));
    return s * s === x;
}

function fermatFactorize(n) {
    if (n <= 0) return null;
    if (n % 2 === 0) return [2, n / 2];

    let a = Math.ceil(Math.sqrt(n));
    let b2 = a * a - n;

    while (!isPerfectSquare(b2)) {
        a += 1;
        b2 = a * a - n;
    }

    const b = Math.sqrt(b2);
    return [a - b, a + b];
}

