import math
import numpy as np
from sympy import isprime

def is_smooth(n, factor_base):
    for p in factor_base:
        while n % p == 0:
            n //= p
    return n == 1

def get_exponent_vector(n, factor_base):
    vector = []
    for p in factor_base:
        exponent = 0
        while n % p == 0:
            n //= p
            exponent += 1
        vector.append(exponent % 2)
    return vector

def gcd(a, b):
    while b:
        a, b = b, a % b
    return abs(a)

def gaussian_elimination(matrix):
    matrix = np.array(matrix, dtype=int)
    rows, cols = matrix.shape
    rank = 0

    for col in range(cols):
        if rank >= rows:
            break

        pivot = -1
        for row in range(rank, rows):
            if matrix[row, col] == 1:
                pivot = row
                break

        if pivot != -1:
            matrix[[rank, pivot]] = matrix[[pivot, rank]]

            for row in range(rows):
                if row != rank and matrix[row, col] == 1:
                    matrix[row] = (matrix[row] + matrix[rank]) % 2

            rank += 1

    return matrix[rank:]

def quadratic_sieve_model(n, factor_base_limit):
    if n % 2 == 0:
        return 2, n // 2

    factor_base = [p for p in range(2, factor_base_limit + 1) if isprime(p) and n % p != 0]
    relations = []
    sqrt_n = math.isqrt(n)

    for k in range(1, 1000):
        x = sqrt_n + k
        y = (x * x) % n

        if is_smooth(y, factor_base):
            exponent_vector = get_exponent_vector(y, factor_base)
            relations.append((x, exponent_vector))

        if len(relations) > len(factor_base):
            break

    if len(relations) <= len(factor_base):
        return None

    matrix = [rel[1] for rel in relations]
    null_space = gaussian_elimination(matrix)

    for null_vector in null_space:
        x_product = 1
        y_product = 1

        for i, bit in enumerate(null_vector):
            if bit == 1:
                x_product = (x_product * relations[i][0]) % n
                y = (relations[i][0] * relations[i][0]) % n
                y_product = (y_product * y) % n

        factor = gcd(abs(x_product - int(math.sqrt(y_product))), n)
        if factor != 1 and factor != n:
            return factor, n // factor

    return None

