import math

def gcd_euclidean(a, b):
    while b:
        a, b = b, a % b
    return a

def lehmers_gcd(a, b):
    a = abs(a)
    b = abs(b)
    if a < b:
        a, b = b, a

    while b != 0:
        if b.bit_length() < 32:
            return gcd_euclidean(a, b)

        n = 32
        a_top = a >> (a.bit_length() - n)
        b_top = b >> (b.bit_length() - n)

        A, B, C, D = 1, 0, 0, 1

        while True:
            q1 = (a_top + A) // (b_top + C)
            q2 = (a_top + B) // (b_top + D)

            if q1 != q2:
                break

            q = q1
            A, B, C, D = C, D, A - q * C, B - q * D
            a_top, b_top = b_top, a_top - q * b_top

        if B == 0:
            a, b = b, a % b
        else:
            new_a = A * a + B * b
            new_b = C * a + D * b
            a = abs(new_a)
            b = abs(new_b)
            if a < b:
                a, b = b, a

    return a

if __name__ == "__main__":
