        return 0
    if exponent == 0:
        return 1
    if exponent == 1:
        return base % modulus

    if exponent % 2 == 0:
        half = mod_exp_recursive(base, exponent // 2, modulus)
        return (half * half) % modulus
    else:
        return (base * mod_exp_recursive(base, exponent - 1, modulus)) % modulus

