class HashTable:
    def __init__(self, size=53):
        self.size = size
        self.key_map = [[] for _ in range(size)]

    def _hash(self, key):
        """Hash function using prime number"""
        total = 0
        weird_prime = 31
        for i in range(min(len(key), 100)):
            char = key[i]
            value = ord(char) - 96
            total = (total * weird_prime + value) % self.size
        return total

    def set(self, key, value):
        """Set key-value pair"""
        index = self._hash(key)
        self.key_map[index].append([key, value])

    def get(self, key):
        """Get value by key"""
        index = self._hash(key)
        if self.key_map[index]:
            for i in range(len(self.key_map[index])):
                if self.key_map[index][i][0] == key:
                    return self.key_map[index][i][1]
        return None

    def has(self, key):
        """Check if key exists"""
        index = self._hash(key)
        if self.key_map[index]:
            for i in range(len(self.key_map[index])):
                if self.key_map[index][i][0] == key:
                    return True
        return False

