def compute_lps_array(pattern):
    """Compute Longest Proper Prefix that is also Suffix (LPS) array"""
    lps = [0] * len(pattern)
    length = 0
    i = 1

    while i < len(pattern):
        if pattern[i] == pattern[length]:
            length += 1
            lps[i] = length
            i += 1
        else:
            if length != 0:
                length = lps[length - 1]
            else:
                lps[i] = 0
                i += 1

    return lps

def knuth_morris_pratt(text, pattern):
