function boyerMoore(text, pattern) {
    const n = text.length;
    const m = pattern.length;

    if (m === 0) return 0;
    if (n < m) return -1;

    // Preprocessing
    const badCharTable = buildBadCharTable(pattern);
    const goodSuffixTable = buildGoodSuffixTable(pattern);

    let i = m - 1; // Index for text
    let j = m - 1; // Index for pattern

    while (i < n) {
        let k = i;
        j = m - 1;

        while (j >= 0 && text[k] === pattern[j]) {
            k--;
            j--;
        }

        if (j === -1) {
            // Match found
            return k + 1;
        }

        const badCharShift = badCharTable[text.charCodeAt(k)] || m;
        const goodSuffixShift = goodSuffixTable[j];

        i += Math.max(badCharShift, goodSuffixShift);
    }

    return -1;
}

function buildBadCharTable(pattern) {
    const table = new Array(256).fill(pattern.length);
    for (let i = 0; i < pattern.length - 1; i++) {
        table[pattern.charCodeAt(i)] = pattern.length - 1 - i;
    }
    return table;
}

function buildGoodSuffixTable(pattern) {
    const m = pattern.length;
    const goodSuffix = new Array(m).fill(m);
    const border = new Array(m + 1).fill(0);

    let i = m;
    let j = m + 1;
    border[i] = j;

    while (i > 0) {
        while (j <= m && pattern.charCodeAt(i - 1) !== pattern.charCodeAt(j - 1)) {
            if (goodSuffix[j] === m) {
                goodSuffix[j] = j - i;
            }
            j = border[j];
        }
        i--;
        j--;
        border[i] = j;
    }

    j = border[0];
    for (i = 0; i <= m; i++) {
        if (goodSuffix[i] === m) {
            goodSuffix[i] = j;
        }
        if (i === j) {
            j = border[j];
        }
    }

    return goodSuffix;
}

