function bucketSort(arr) {
    const n = arr.length;
    if (n <= 1) return arr;

    const min = Math.min(...arr);
    const max = Math.max(...arr);
    const range = max - min;

    // Check for a range of 0 to prevent division by zero
    if (range === 0) {
        return arr; // Array is already sorted
    }

    const bucketCount = n;
    const buckets = Array.from({ length: bucketCount }, () => []);

    for (let i = 0; i < n; i++) {
        const normalizedValue = (arr[i] - min) / range;
        const bucketIndex = Math.floor(normalizedValue * (bucketCount - 1));
        buckets[bucketIndex].push(arr[i]);
    }

    const result = [];
    for (const bucket of buckets) {
        bucket.sort((a, b) => a - b);
        result.push(...bucket);
    }

    return result;
}

