import heapq

def patience_sort(arr):
    if not arr:
        return arr

    piles = []

    for card in arr:
        low = 0
        high = len(piles) - 1
        insertion_index = len(piles)

        while low <= high:
            mid = (low + high) // 2
            if piles[mid][-1] >= card:
                insertion_index = mid
                high = mid - 1
            else:
                low = mid + 1

        if insertion_index < len(piles):
            piles[insertion_index].append(card)
        else:
            piles.append([card])

    result = []
    heap = []

    for i, pile in enumerate(piles):
        if pile:
            heapq.heappush(heap, (pile.pop(), i))

    while heap:
        value, pile_index = heapq.heappop(heap)
        result.append(value)

        if piles[pile_index]:
            heapq.heappush(heap, (piles[pile_index].pop(), pile_index))

    return result

