            if (piles[mid][piles[mid].length - 1] >= card) {
                insertionIndex = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }

        if (insertionIndex < piles.length) {
            piles[insertionIndex].push(card);
        } else {
            piles.push([card]);
        }
    }

    // Step 2: Merge piles using a min-heap
    const result = [];
    const minHeap = [];

    // Custom heapify function for min-heap
    const swap = (arr, i, j) => [arr[i], arr[j]] = [arr[j], arr[i]];

    const heapify = (heap, index) => {
        const left = 2 * index + 1;
        const right = 2 * index + 2;
        let smallest = index;

        if (left < heap.length && heap[left].value < heap[smallest].value) {
            smallest = left;
        }

        if (right < heap.length && heap[right].value < heap[smallest].value) {
            smallest = right;
        }

        if (smallest !== index) {
            swap(heap, index, smallest);
            heapify(heap, smallest);
        }
    };

    const extractMin = (heap) => {
        if (heap.length === 0) return null;
        if (heap.length === 1) return heap.pop();
        const min = heap[0];
        heap[0] = heap.pop();
        heapify(heap, 0);
        return min;
    };

    const insertHeap = (heap, item) => {
        heap.push(item);
        let current = heap.length - 1;
        let parent = Math.floor((current - 1) / 2);
        while (current > 0 && heap[current].value < heap[parent].value) {
            swap(heap, current, parent);
            current = parent;
            parent = Math.floor((current - 1) / 2);
        }
    };

    for (let i = 0; i < piles.length; i++) {
        if (piles[i].length > 0) {
            insertHeap(minHeap, {
                value: piles[i].pop(),
                pileIndex: i
            });
        }
    }

    while (minHeap.length > 0) {
        const min = extractMin(minHeap);
        result.push(min.value);

        if (piles[min.pileIndex].length > 0) {
            insertHeap(minHeap, {
                value: piles[min.pileIndex].pop(),
                pileIndex: min.pileIndex
            });
        }
    }

    return result;
}

