def inverse_matrix(matrix):
    n = len(matrix)
    if n != len(matrix[0]):
        return None

    identity = [[0 for _ in range(n)] for _ in range(n)]
    for i in range(n):
        identity[i][i] = 1

    augmented_matrix = [row + identity[i] for i, row in enumerate(matrix)]

    for i in range(n):
        pivot = augmented_matrix[i][i]
        if pivot == 0:
            return None

        for j in range(2 * n):
            augmented_matrix[i][j] /= pivot

        for k in range(n):
            if i != k:
                factor = augmented_matrix[k][i]
                for j in range(2 * n):
                    augmented_matrix[k][j] -= factor * augmented_matrix[i][j]

    inverse = [[augmented_matrix[i][j] for j in range(n, 2 * n)] for i in range(n)]

    return inverse

