def power_iteration(matrix, num_iterations):
    n = len(matrix)
    if n == 0 or n != len(matrix[0]):
        return None, None

    x = [random.random() for _ in range(n)]

    for _ in range(num_iterations):
        y = [0.0] * n
        for i in range(n):
            for j in range(n):
                y[i] += matrix[i][j] * x[j]

        magnitude = sum([val ** 2 for val in y]) ** 0.5
        if magnitude == 0:
