    const y = new Array(n).fill(0.0);
    for (let i = 0; i < n; i++) {
      for (let j = 0; j < n; j++) {
        y[i] += matrix[i][j] * x[j];
      }
    }

    let magnitude = 0;
    for (let val of y) {
      magnitude += val * val;
    }
    magnitude = Math.sqrt(magnitude);

    if (magnitude === 0) {
      return null;
    }

    x = y.map(val => val / magnitude);
  }

  let eigenvalue = 0;
  const yLast = new Array(n).fill(0.0);
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      yLast[i] += matrix[i][j] * x[j];
    }
  }
  for (let i = 0; i < n; i++) {
      eigenvalue += x[i] * yLast[i];
  }

  return { eigenvalue, eigenvector: x };
}

