function pluDecomposition(matrix) {
    const n = matrix.length;
    if (n !== matrix[0].length) {
        return null;
    }

    const P = new Array(n).fill(0).map((_, i) => new Array(n).fill(0).map((_, j) => (i === j ? 1 : 0)));
    const L = new Array(n).fill(0).map((_, i) => new Array(n).fill(0).map((_, j) => (i === j ? 1 : 0)));
    const U = matrix.map(row => [...row]);

    for (let i = 0; i < n; i++) {
        let pivotRow = i;
        for (let k = i + 1; k < n; k++) {
            if (Math.abs(U[k][i]) > Math.abs(U[pivotRow][i])) {
                pivotRow = k;
            }
        }

        if (pivotRow !== i) {
            [U[i], U[pivotRow]] = [U[pivotRow], U[i]];
            [P[i], P[pivotRow]] = [P[pivotRow], P[i]];
            for (let j = 0; j < i; j++) {
                [L[i][j], L[pivotRow][j]] = [L[pivotRow][j], L[i][j]];
            }
        }

        if (U[i][i] === 0) {
            return null;
        }

        for (let j = i + 1; j < n; j++) {
            L[j][i] = U[j][i] / U[i][i];
            for (let k = i; k < n; k++) {
                U[j][k] -= L[j][i] * U[i][k];
            }
        }
    }

    return { P, L, U };
}

