function qrDecomposition(matrix) {
  const m = matrix.length;
  if (m === 0) {
    return null;
  }
  const n = matrix[0].length;
  if (m < n) {
    return null;
  }

  const Q = new Array(m).fill(0).map(() => new Array(n).fill(0));
  const R = new Array(n).fill(0).map(() => new Array(n).fill(0));

  for (let j = 0; j < n; j++) {
    const v = matrix.map(row => row[j]);

    for (let i = 0; i < j; i++) {
      let dotProduct = 0;
      for (let k = 0; k < m; k++) {
        dotProduct += Q[k][i] * v[k];
      }
      R[i][j] = dotProduct;

      for (let k = 0; k < m; k++) {
        v[k] -= R[i][j] * Q[k][i];
      }
    }

    let norm = 0;
    for (let val of v) {
      norm += val * val;
    }
    norm = Math.sqrt(norm);

    if (Math.abs(norm) < 1e-12) {
      return null;
    }

    R[j][j] = norm;
    for (let i = 0; i < m; i++) {
      Q[i][j] = v[i] / norm;
    }
  }

  return { Q, R };
}

