               matrix[0][2] * (matrix[1][0] * matrix[2][1] - matrix[1][1] * matrix[2][0]))

    if det == 0:
        return None

    cofactor_matrix = [[0 for _ in range(n)] for _ in range(n)]
    for i in range(n):
