        det = matrix[0][0] * (matrix[1][1] * matrix[2][2] - matrix[1][2] * matrix[2][1]) -
              matrix[0][1] * (matrix[1][0] * matrix[2][2] - matrix[1][2] * matrix[2][0]) +
              matrix[0][2] * (matrix[1][0] * matrix[2][1] - matrix[1][1] * matrix[2][0]);
    }

    if (det === 0) {
        return null;
    }

    const cofactorMatrix = new Array(n).fill(0).map(() => new Array(n).fill(0));
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            if (n === 1) {
                cofactorMatrix[i][j] = 1;
            } else {
                const submatrix = getSubmatrix(matrix, i, j);
                let subDet = 0;
                if (submatrix.length === 1) {
                    subDet = submatrix[0][0];
                } else if (submatrix.length === 2) {
                    subDet = getDeterminant2x2(submatrix);
                }

                const sign = (i + j) % 2 === 0 ? 1 : -1;
                cofactorMatrix[i][j] = sign * subDet;
            }
        }
    }

    const adjugateMatrix = new Array(n).fill(0).map(() => new Array(n).fill(0));
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            adjugateMatrix[i][j] = cofactorMatrix[j][i];
        }
    }

    const inverse = adjugateMatrix.map(row => row.map(elem => elem / det));
    return inverse;
}

function getDeterminant2x2(matrix) {
    return matrix[0][0] * matrix[1][1] - matrix[0][1] * matrix[1][0];
}

function getSubmatrix(matrix, row, col) {
    const n = matrix.length;
    const submatrix = [];
    for (let i = 0; i < n; i++) {
        if (i !== row) {
            const newRow = [];
            for (let j = 0; j < n; j++) {
                if (j !== col) {
                    newRow.push(matrix[i][j]);
                }
            }
            submatrix.push(newRow);
        }
    }
    return submatrix;
  }
