def is_symmetric(matrix):
    if not matrix or not all(len(row) == len(matrix) for row in matrix):
        return False

    n = len(matrix)
    for i in range(n):
        for j in range(i + 1, n):
            if matrix[i][j] != matrix[j][i]:
                return False
    return True

def is_skew_symmetric(matrix):
    if not matrix or not all(len(row) == len(matrix) for row in matrix):
        return False

    n = len(matrix)
    for i in range(n):
        if matrix[i][i] != 0:
            return False
        for j in range(i + 1, n):
            if matrix[i][j] != -matrix[j][i]:
                return False
    return True

