def solve_gaussian_elimination(matrix):
    n = len(matrix)
    if n == 0 or n != len(matrix[0]) - 1:
        return None

    for i in range(n):
        pivot_row = i
        for k in range(i + 1, n):
            if abs(matrix[k][i]) > abs(matrix[pivot_row][i]):
                pivot_row = k

        matrix[i], matrix[pivot_row] = matrix[pivot_row], matrix[i]

        if matrix[i][i] == 0:
            return None

        for k in range(i + 1, n):
            factor = matrix[k][i] / matrix[i][i]
            for j in range(i, n + 1):
                matrix[k][j] -= factor * matrix[i][j]

    x = [0 for _ in range(n)]
    for i in range(n - 1, -1, -1):
        sum_val = sum(matrix[i][j] * x[j] for j in range(i + 1, n))
        x[i] = (matrix[i][n] - sum_val) / matrix[i][i]

    return x

