import math

def cholesky_decomposition(matrix):
    n = len(matrix)
    if n != len(matrix[0]):
        return None

    L = [[0.0] * n for _ in range(n)]

    for i in range(n):
        for j in range(i + 1):
            sum_val = sum(L[i][k] * L[j][k] for k in range(j))

            if i == j:
                diag_val = matrix[i][i] - sum_val
                if diag_val <= 0:
                    return None
                L[i][j] = math.sqrt(diag_val)
            else:
                L[i][j] = (matrix[i][j] - sum_val) / L[j][j]

    return L

