def gauss_seidel(matrix, b, max_iterations, tolerance):
    n = len(matrix)
    if n == 0 or n != len(matrix[0]) or n != len(b):
        return None

    x = [0.0] * n

    for iter_count in range(max_iterations):
        x_new = list(x)
        for i in range(n):
            if matrix[i][i] == 0:
                return None

            sum1 = sum(matrix[i][j] * x_new[j] for j in range(i))
            sum2 = sum(matrix[i][j] * x[j] for j in range(i + 1, n))

            x_new[i] = (b[i] - sum1 - sum2) / matrix[i][i]

        diff = sum(abs(x_new[i] - x[i]) for i in range(n))
        x = x_new

        if diff < tolerance:
            return x

    return x

