def jacobi_iteration(matrix, b, max_iterations, tolerance):
    n = len(matrix)
    if n == 0 or n != len(matrix[0]) or n != len(b):
        return None

    x = [0.0] * n

    for _ in range(max_iterations):
        x_new = [0.0] * n
        diff = 0.0
        for i in range(n):
            if matrix[i][i] == 0:
                return None

            sum_val = sum(matrix[i][j] * x[j] for j in range(n) if i != j)
            x_new[i] = (b[i] - sum_val) / matrix[i][i]

            diff += abs(x_new[i] - x[i])

        x = x_new

        if diff < tolerance:
            return x

    return x

